def is_good(m):
    # Constraint check: distinct nonzero digits
    s_m = str(m)
    if any(c == '0' for c in s_m):
        return False
    if len(set(s_m)) != len(s_m):
        return False

    # 1. Single-digit numbers are good
    if len(s_m) == 1:
        return True

    # 2. Check removal criteria
    digits = [int(d) for d in s_m]
    n = len(digits)

    for i in range(n):
        # Create the number m_removed by removing digit i
        m_removed_str = "".join(map(str, digits[:i] + digits[i+1:]))

        if not m_removed_str:
            # Should not happen if n >= 2
            continue

        m_removed = int(m_removed_str)

        # Check if m_removed is a divisor of m
        if m % m_removed == 0:
            # Check if m_removed is a good number
            if is_good(m_removed):
                return True

    return False

