             if is_good(m):
                 two_digit_good.append(m)

print("2-digit good numbers found:", sorted(two_digit_good))

def has_distinct_nonzero_digits(m):
    s = str(m)
    if not s:
        return False

    digits = set()
    for char in s:
        digit = int(char)
        if digit == 0:
            return False  # Must be nonzero
        if digit in digits:
            return False  # Must be distinct
        digits.add(digit)
    return True

# Memoization for efficiency
memo = {}

def is_good(m):
    if m in memo:
        return memo[m]

    # Constraint check: m must consist of distinct nonzero digits to be considered good
    if not has_distinct_nonzero_digits(m):
        return False

    # Base Case 1: Single-digit number (and non-zero, guaranteed by check above)
    if m < 10:
        return True

    s = str(m)

    # Recursive Step: Check if removing any digit results in a good divisor
    for i in range(len(s)):
        # Form the number d by removing the digit at index i
        d_str = s[:i] + s[i+1:]

        # Handle case where d_str might be empty if m was 1 digit, but we handled m < 10 already.
        if not d_str:
            continue

        d = int(d_str)

        # d must be positive for division checks to make sense
        if d == 0:
            continue

        # Check conditions:
        # 1. d is a divisor of m
        is_divisor = (m % d == 0)

        # 2. d is a good number (recursive check)
        d_is_good = is_good(d)

        if is_divisor and d_is_good:
            memo[m] = True
            return True

    memo[m] = False
    return False

